def parse_semver(version):
    'Parses a semantic version string into a (major, minor, patch) tuple.'
    parts = version.split('.')
    if len(parts) < 3:
        raise ValueError('Invalid semantic version format. Must have at least major.minor.patch')

    major = int(parts[0])
    minor = int(parts[1])
    patch_str = parts[2]

    # Handle pre-release and build metadata if present
    if '-' in patch_str:
        patch = int(patch_str.split('-')[0])
    elif '+' in patch_str:
        patch = int(patch_str.split('+')[0])
    else:
        patch = int(patch_str)

    return (major, minor, patch)
