    flattened_data = {}

    def _flatten(obj, name=''):
        if isinstance(obj, dict):
            for k, v in obj.items():
                _flatten(v, name + k + sep)
        elif isinstance(obj, list):
            for idx, item in enumerate(obj):
                _flatten(item, name + str(idx) + sep)
        else:
            if name.endswith(sep):
                flattened_data[name[:-len(sep)]] = obj
            else:
                flattened_data[name] = obj

    _flatten(d)
    return flattened_data
