import collections
import functools

def lru_cache_decorator(maxsize):
    '''
    A simple LRU cache decorator.

    Args:
        maxsize (int): The maximum number of items to store in the cache.
                       If maxsize is 0, the cache is disabled.
                       If maxsize is None, the cache is unbounded.
    '''
    def decorator(func):
        if maxsize is None:
            cache = {}
        elif maxsize == 0:
            def wrapper_no_cache(*args, **kwargs):
                return func(*args, **kwargs)
            return wrapper_no_cache
        else:
            cache = collections.OrderedDict()

        @functools.wraps(func)
        def wrapper(*args, **kwargs):
            # Create a cache key from args and kwargs
            # For simplicity, we'll assume args are hashable and kwargs are sorted by key
            key = (args, tuple(sorted(kwargs.items())))

            if key in cache:
