def flatten_dict(d, sep='.'):
    """
    Flattens a nested dictionary into a single-level dictionary with concatenated keys.

    Args:
        d (dict): The dictionary to flatten.
        sep (str, optional): The separator to use for concatenating keys. Defaults to '.'.

    Returns:
        dict: A new dictionary with all nested keys flattened.

    Examples:
        >>> d = {'a': 1, 'b': {'c': 2, 'd': {'e': 3}}}
        >>> flatten_dict(d)
        {'a': 1, 'b.c': 2, 'b.d.e': 3}

        >>> d = {'user': {'name': 'Alice', 'address': {'city': 'NY', 'zip': '10001'}}, 'id': 123}
        >>> flatten_dict(d, sep='_')
        {'user_name': 'Alice', 'user_address_city': 'NY', 'user_address_zip': '10001', 'id': 123}

        >>> flatten_dict({})
        {}

        >>> flatten_dict({'a': [1, 2], 'b': {'c': None}})
        {'a': [1, 2], 'b.c': None}
    """
    flat_dict = {}

    def _flatten(obj, prefix=''):
        if isinstance(obj, dict):
            for k, v in obj.items():
                new_prefix = f"{prefix}{sep}{k}" if prefix else k
                _flatten(v, new_prefix)
        else:
            flat_dict[prefix] = obj

    _flatten(d)
    return flat_dict
```

