            for i, item in enumerate(obj):
                new_key = f'{prefix}{i}'
                _flatten(item, new_key + sep)
        else:
            flattened_dict[prefix[:-len(sep)] if prefix else ''] = obj

    _flatten(d)
    return flattened_dict
